package playground.dcb;
import static playground.dcb.Dcb.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import java.util.function.*;
import java.sql.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** JSON-only persistence boundary. Payload codecs belong to the application. */
public final class JsonStore<E> implements CommandStore<E>,AutoCloseable {
 public record Row(int position,String commandId,String eventType,String payloadJson,String tagsJson){}
 public record RawRead(int after,List<Row> events){}
 public record RawAppend(boolean committed,List<Row> events){}
 public interface Journal extends AutoCloseable{RawRead read(Query q,int after);RawAppend append(String id,Query q,int after,List<Row> events);String version();void load(List<Row> rows);void close();}
 private static final ObjectMapper metadata=new ObjectMapper();
 public static byte[] keys(List<String> keys){int n=0;for(var k:keys)n+=4+k.getBytes(StandardCharsets.UTF_8).length;var b=ByteBuffer.allocate(n);for(var k:keys){var bytes=k.getBytes(StandardCharsets.UTF_8);b.putInt(bytes.length).put(bytes);}return b.array();}
 private static String key(Tag t){var ks=new ArrayList<String>();ks.add(t.category());ks.addAll(t.keys());return HexFormat.of().formatHex(keys(ks));}
 public static List<Tag> tags(String json){Tag[] a;try{a=metadata.readValue(json,Tag[].class);}catch(Exception e){throw new IllegalArgumentException(e);}var out=List.of(a);if(out.stream().map(JsonStore::key).distinct().count()!=out.size())throw new IllegalArgumentException("duplicate tag");return out;}
 public static final class Memory implements Journal{
  private final List<Row> log=new ArrayList<>();private final Map<String,List<Integer>> tags=new HashMap<>(),types=new HashMap<>();
  private SortedSet<Integer> candidates(Query q,int after){if(after<0||after>log.size())throw new IllegalArgumentException("invalid position");var result=new TreeSet<Integer>();var items=q.items().isEmpty()?List.of(new QueryItem(List.of(),List.of())):q.items();for(var item:items){var sets=new ArrayList<List<Integer>>();for(var t:item.tags())sets.add(tags.getOrDefault(key(t),List.of()));if(!item.types().isEmpty()){var ps=new ArrayList<Integer>();for(var t:item.types())ps.addAll(types.getOrDefault(t,List.of()));sets.add(ps);}if(sets.isEmpty()){for(int p=after+1;p<=log.size();p++)result.add(p);continue;}var selected=new HashSet<>(sets.getFirst());for(var ps:sets.subList(1,sets.size()))selected.retainAll(new HashSet<>(ps));selected.removeIf(p->p<=after);result.addAll(selected);}return result;}
  public synchronized RawRead read(Query q,int after){return new RawRead(log.size(),candidates(q,after).stream().map(p->log.get(p-1)).toList());}
  public synchronized RawAppend append(String id,Query q,int after,List<Row> rows){if(id.isEmpty()||rows.isEmpty())throw new IllegalArgumentException("invalid append");if(!candidates(q,after).isEmpty())return new RawAppend(false,List.of());var pending=new ArrayList<Row>();for(var e:rows){tags(e.tagsJson());pending.add(new Row(log.size()+pending.size()+1,id,e.eventType(),e.payloadJson(),e.tagsJson()));}for(var e:pending){log.add(e);types.computeIfAbsent(e.eventType(),x->new ArrayList<>()).add(e.position());for(var t:tags(e.tagsJson()))tags.computeIfAbsent(key(t),x->new ArrayList<>()).add(e.position());}return new RawAppend(true,List.copyOf(pending));}
  public synchronized void load(List<Row>rows){if(!log.isEmpty())throw new IllegalStateException("load requires empty journal");for(int i=0;i<rows.size();i++){if(rows.get(i).position()!=i+1)throw new IllegalArgumentException("invalid position");tags(rows.get(i).tagsJson());}for(var e:rows){log.add(e);types.computeIfAbsent(e.eventType(),x->new ArrayList<>()).add(e.position());for(var t:tags(e.tagsJson()))tags.computeIfAbsent(key(t),x->new ArrayList<>()).add(e.position());}}
  public String version(){return "memory-json-v1";}public void close(){}
 }
 public static final class Sqlite implements Journal{
  private final Connection db;private final Map<String,PreparedStatement> statements=new HashMap<>();private final String version;
  public Sqlite(String path,String durability){try{if(!List.of("FULL","NORMAL").contains(durability))throw new IllegalArgumentException("invalid durability");Files.createDirectories(Path.of(path).toAbsolutePath().getParent());db=DriverManager.getConnection("jdbc:sqlite:"+path);for(var q:List.of("PRAGMA journal_mode=WAL","PRAGMA synchronous="+durability,"PRAGMA foreign_keys=ON","PRAGMA busy_timeout=5000","PRAGMA cache_size=-2048","PRAGMA wal_autocheckpoint=1000","CREATE TABLE IF NOT EXISTS events(position INTEGER PRIMARY KEY,command_id TEXT NOT NULL,event_type TEXT NOT NULL,payload_json TEXT NOT NULL,tags_json TEXT NOT NULL)","CREATE TABLE IF NOT EXISTS event_tags(position INTEGER NOT NULL REFERENCES events(position),category TEXT NOT NULL,keys_key BLOB NOT NULL,PRIMARY KEY(position,category,keys_key))","CREATE INDEX IF NOT EXISTS tags_match ON event_tags(category,keys_key,position)","CREATE INDEX IF NOT EXISTS events_type_position ON events(event_type,position)"))exec(q);int v;try(var r=stmt("PRAGMA user_version").executeQuery()){r.next();v=r.getInt(1);}if(v!=0&&v!=1)throw new IllegalStateException("unsupported schema version");exec("PRAGMA user_version=1");try(var r=stmt("SELECT sqlite_version()").executeQuery()){r.next();version=r.getString(1);}}catch(Exception e){throw new IllegalStateException(e);}}
  private PreparedStatement stmt(String q)throws SQLException{var p=statements.get(q);if(p==null){p=db.prepareStatement(q);statements.put(q,p);}p.clearParameters();return p;}
  private PreparedStatement bind(String q,List<Object>args)throws SQLException{var p=stmt(q);for(int i=0;i<args.size();i++){var v=args.get(i);if(v instanceof byte[] b)p.setBytes(i+1,b);else p.setObject(i+1,v);}return p;}
  private void exec(String q)throws SQLException{try(var s=db.createStatement()){if(s.execute(q)){try(var r=s.getResultSet()){while(r.next()) {}}}}}
  private int high()throws SQLException{try(var r=stmt("SELECT COALESCE(MAX(position),0) FROM events").executeQuery()){r.next();return r.getInt(1);}}
  private record Selection(String sql,List<Object>args){}
  private Selection selection(Query q,int low,int high,boolean exists){var args=new ArrayList<Object>();Function<Object,String>param=v->{args.add(v);return "?";};Supplier<String>range=()->"position>"+param.apply(low)+" AND position<="+param.apply(high);String condition;if(q.items().isEmpty()||q.items().stream().anyMatch(i->i.tags().isEmpty()&&i.types().isEmpty()))condition=range.get();else{var alts=new ArrayList<String>();for(var item:q.items()){var terms=new ArrayList<String>();for(var t:item.tags())terms.add("SELECT position FROM event_tags WHERE category="+param.apply(t.category())+" AND keys_key="+param.apply(keys(t.keys()))+" AND "+range.get());if(!item.types().isEmpty())terms.add("SELECT position FROM events WHERE event_type IN ("+String.join(",",item.types().stream().map(param).toList())+") AND "+range.get());alts.add("SELECT position FROM ("+String.join(" INTERSECT ",terms)+")");}condition="position IN ("+String.join(" UNION ",alts)+")";}return new Selection("SELECT "+(exists?"1":"position,command_id,event_type,payload_json,tags_json")+" FROM events WHERE "+condition+(exists?" LIMIT 1":" ORDER BY position"),args);}
  public synchronized RawRead read(Query q,int after){try{exec("BEGIN");int high=high();if(after<0||after>high)throw new IllegalArgumentException("invalid position");var sel=selection(q,after,high,false);var out=new ArrayList<Row>();try(var r=bind(sel.sql(),sel.args()).executeQuery()){while(r.next())out.add(new Row(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)));}exec("COMMIT");return new RawRead(high,out);}catch(Exception e){rollback();throw new IllegalStateException(e);}}
  public synchronized RawAppend append(String id,Query q,int after,List<Row>rows){try{exec("BEGIN IMMEDIATE");int high=high();if(id.isEmpty()||rows.isEmpty()||after<0||after>high)throw new IllegalArgumentException("invalid append");var sel=selection(q,after,high,true);try(var r=bind(sel.sql(),sel.args()).executeQuery()){if(r.next()){exec("ROLLBACK");return new RawAppend(false,List.of());}}var pending=new ArrayList<Row>();for(var e:rows){var row=new Row(high+pending.size()+1,id,e.eventType(),e.payloadJson(),e.tagsJson());bind("INSERT INTO events VALUES(?,?,?,?,?)",List.of(row.position(),id,row.eventType(),row.payloadJson(),row.tagsJson())).executeUpdate();for(var t:tags(row.tagsJson()))bind("INSERT INTO event_tags VALUES(?,?,?)",List.of(row.position(),t.category(),keys(t.keys()))).executeUpdate();pending.add(row);}exec("COMMIT");return new RawAppend(true,pending);}catch(Exception e){rollback();throw new IllegalStateException(e);}}
  public synchronized void load(List<Row>rows){try{exec("BEGIN IMMEDIATE");if(high()!=0)throw new IllegalStateException("load requires empty journal");for(int i=0;i<rows.size();i++){var e=rows.get(i);if(e.position()!=i+1)throw new IllegalArgumentException("invalid position");bind("INSERT INTO events VALUES(?,?,?,?,?)",List.of(e.position(),e.commandId(),e.eventType(),e.payloadJson(),e.tagsJson())).executeUpdate();for(var t:tags(e.tagsJson()))bind("INSERT INTO event_tags VALUES(?,?,?)",List.of(e.position(),t.category(),keys(t.keys()))).executeUpdate();}exec("COMMIT");}catch(Exception e){rollback();throw new IllegalStateException(e);}}
  private void rollback(){try{exec("ROLLBACK");}catch(SQLException ignored){}}
  public String version(){return version;}public void close(){try{for(var p:statements.values())p.close();db.close();}catch(SQLException e){throw new IllegalStateException(e);}}
 }
 private final Journal journal;private final Function<E,EventDescriptor>describe;private final Function<E,String>encode;private final Function<String,E>decode;private final List<Predicate<List<Recorded<E>>>>listeners=new ArrayList<>();private int published,faults;public long encoded,decoded,encodedBytes,decodedBytes;
 public JsonStore(Journal j,Function<E,EventDescriptor>d,Function<E,String>e,Function<String,E>r){journal=j;describe=d;encode=e;decode=r;}
 private static String jsonTags(List<Tag> tags){try{return metadata.writeValueAsString(tags);}catch(Exception e){throw new IllegalArgumentException(e);}}
 private Row encodeEvent(String id,E e){var d=describe.apply(e);if(d.eventType().isEmpty())throw new IllegalArgumentException("event type required");var json=encode.apply(e);encoded++;encodedBytes+=json.getBytes(StandardCharsets.UTF_8).length;return new Row(0,id,d.eventType(),json,jsonTags(d.tags()));}
 private List<Recorded<E>>decodeRows(List<Row>rows){return rows.stream().map(e->{var p=decode.apply(e.payloadJson());var ts=tags(e.tagsJson());var d=describe.apply(p);if(!d.eventType().equals(e.eventType())||ts.size()!=d.tags().size()||!ts.containsAll(d.tags()))throw new IllegalArgumentException("invalid stored metadata");decoded++;decodedBytes+=e.payloadJson().getBytes(StandardCharsets.UTF_8).length;return new Recorded<>(e.position(),e.commandId(),e.eventType(),ts,p);}).toList();}
 public synchronized ReadResult<E>read(Query q){var r=journal.read(q,0);return new ReadResult<>(r.after(),decodeRows(r.events()));}
 public synchronized void refresh(){if(listeners.isEmpty())return;var r=journal.read(new Query(List.of()),published);var events=decodeRows(r.events());listeners.removeIf(l->{try{if(l.test(events))return false;}catch(RuntimeException ignored){}faults++;return true;});published=r.after();}
 public synchronized AppendResult<E>append(String id,Query q,int after,List<E>events){var r=journal.append(id,q,after,events.stream().map(e->encodeEvent(id,e)).toList());if(!r.committed())return new AppendResult<>(false,List.of());if(listeners.isEmpty())published=r.events().getLast().position();else refresh();return new AppendResult<>(true,decodeRows(r.events()));}
 public synchronized void subscribe(Predicate<List<Recorded<E>>>l){if(!listeners.isEmpty())refresh();var r=journal.read(new Query(List.of()),0);if(!l.test(decodeRows(r.events())))throw new IllegalStateException("replay failed");listeners.add(l);published=r.after();}
 public synchronized void load(List<Recorded<E>>events){if(!listeners.isEmpty())throw new IllegalStateException("load before subscribe");var rows=new ArrayList<Row>();for(int i=0;i<events.size();i++){var e=events.get(i);var row=encodeEvent(e.commandId(),e.payload());var ts=tags(row.tagsJson());if(e.position()!=i+1||e.commandId().isEmpty()||!e.eventType().equals(row.eventType())||e.tags().size()!=ts.size()||!ts.containsAll(e.tags()))throw new IllegalArgumentException("invalid imported metadata");rows.add(new Row(e.position(),e.commandId(),row.eventType(),row.payloadJson(),row.tagsJson()));}journal.load(rows);}
 public int listenerFaults(){return faults;}public String version(){return journal.version();}public void close(){journal.close();}
}
